INSERT INTO public.recipes (id, title, cuisine, budget_tier, goals, minutes, equipment_tags, servings, steps, macros, cost_per_serving, cost_full_pack, image_url, emoji, gradient_seed) VALUES
(1, '10-Minute Kanda Poha with Peanuts', 'Indian', 'broke', ARRAY['15-min','fat-loss'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Rinse poha in a colander under running water for 30s and drain well.","timer_seconds":30,"tip":"Do not soak or poha becomes mushy!"},{"text":"Heat oil in a pan, fry peanuts until crunchy, then add mustard seeds and green chilli.","timer_seconds":90},{"text":"Sauté chopped onion (kanda) until translucent and soft.","timer_seconds":120},{"text":"Add turmeric, salt, drained poha, and toss gently on low heat.","timer_seconds":180},{"text":"Finish with fresh coriander and a squeeze of lemon juice.","tip":"Add a boiled egg on the side for 6g extra protein."}]'::jsonb, '{"kcal":290,"protein":7.2,"carbs":48,"fats":8.5,"fiber":3.4}'::jsonb, 24, 110, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80', '🍚', 101),
(2, 'One-Pot Moong Dal Khichdi', 'Indian', 'broke', ARRAY['fat-loss','15-min'], 15, ARRAY['1-pan','kettle-only','hostel-friendly'], 1, '[{"text":"Rinse rice and moong dal together thoroughly.","timer_seconds":60},{"text":"In your kettle or pan, heat ghee with cumin seeds (jeera) and ginger.","timer_seconds":90},{"text":"Add rinsed dal-rice mix with 3 cups water, turmeric, and salt.","timer_seconds":600,"tip":"Add an extra half cup of water for comforting soul-food consistency."},{"text":"Cook until soft and creamy. Serve hot with a spoonful of dahi.","tip":"High satiety survival staple under ₹35."}]'::jsonb, '{"kcal":340,"protein":17.5,"carbs":54,"fats":6,"fiber":5.5}'::jsonb, 32, 140, 'https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=600&q=80', '🍲', 102),
(3, 'Masala Oats with Boiled Eggs', 'Indian', 'broke', ARRAY['high-protein','15-min'], 12, ARRAY['1-pan','kettle-only'], 1, '[{"text":"Boil 2 eggs in your kettle or small pot for 8 minutes.","timer_seconds":480},{"text":"In a pan, sauté onion, tomato, and green chilli with a pinch of garam masala.","timer_seconds":120},{"text":"Add rolled oats and 1.5 cups water. Cook for 3 minutes until thick.","timer_seconds":180},{"text":"Peel eggs, slice in half, place on top with cracked black pepper.","tip":"26g protein power breakfast for under ₹40."}]'::jsonb, '{"kcal":380,"protein":26,"carbs":38,"fats":14,"fiber":6}'::jsonb, 36, 145, 'https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=600&q=80', '🍳', 103),
(4, 'Paneer Tikka Quinoa Bowl', 'Indian', 'balanced', ARRAY['high-protein','muscle-gain'], 20, ARRAY['1-pan','induction'], 1, '[{"text":"Cook quinoa in salted water (1:2 ratio) for 12 minutes.","timer_seconds":720},{"text":"Cube paneer and toss with curd, red chilli powder, turmeric, and garam masala.","timer_seconds":180},{"text":"Sear marinated paneer on a hot pan for 2-3 mins per side until charred edges appear.","timer_seconds":240},{"text":"Assemble quinoa in bowl, top with paneer tikka, sliced onions, and chopped coriander.","tip":"Drizzle with mint chutney or lemon juice."}]'::jsonb, '{"kcal":540,"protein":34,"carbs":46,"fats":24,"fiber":7}'::jsonb, 95, 280, 'https://images.unsplash.com/photo-1631515243349-e0cb75fb8d3a?auto=format&fit=crop&w=600&q=80', '🥗', 104),
(5, 'Truffle Mushroom Fettuccine', 'Italian', 'hifi', ARRAY['muscle-gain'], 18, ARRAY['1-pan','induction'], 1, '[{"text":"Boil fettuccine pasta in heavily salted rolling water until al dente.","timer_seconds":540},{"text":"In a pan, melt butter and sauté sliced button mushrooms with minced garlic.","timer_seconds":240},{"text":"Add cooked fettuccine with 2 tbsp pasta water and emulsion toss.","timer_seconds":90},{"text":"Remove from heat, drizzle 1 tsp artisan truffle oil and grate cheese.","tip":"Never boil truffle oil directly — its delicate aroma is best preserved as a finishing drizzle."}]'::jsonb, '{"kcal":620,"protein":21,"carbs":74,"fats":28,"fiber":5.2}'::jsonb, 290, 650, 'https://images.unsplash.com/photo-1621996346565-e3d5d6281691?auto=format&fit=crop&w=600&q=80', '🍝', 105),
(6, 'Dragon Fruit & Blueberry Açaí Glow Bowl', 'Continental', 'hifi', ARRAY['fat-loss','15-min'], 8, ARRAY['mixer','hostel-friendly'], 1, '[{"text":"Blend frozen dragon fruit cubes, acai puree, and 1 ripe banana until velvety thick.","timer_seconds":90},{"text":"Pour thick smoothie base into chilled bowl.","timer_seconds":30},{"text":"Artfully arrange sliced dragon fruit, crunchy granola, and chia seeds.","tip":"Gourmet cafe antioxidant booster ready in 8 mins flat."}]'::jsonb, '{"kcal":410,"protein":12,"carbs":76,"fats":8,"fiber":14}'::jsonb, 245, 520, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=600&q=80', '🫐', 106),
(7, 'Sourdough Avocado Poached Eggs', 'Continental', 'hifi', ARRAY['high-protein','15-min'], 12, ARRAY['1-pan'], 1, '[{"text":"Toast sourdough slice in pan with a touch of butter until golden and crisp.","timer_seconds":180},{"text":"Mash ripe avocado with salt, pepper, and lime juice.","timer_seconds":60},{"text":"Poach or soft-fry 2 eggs in boiling water/pan for 3 minutes.","timer_seconds":180},{"text":"Spread avocado over toast, top with warm eggs and chilli flakes.","tip":"Slice open yolks for that iconic golden runny texture."}]'::jsonb, '{"kcal":490,"protein":24,"carbs":36,"fats":28,"fiber":9}'::jsonb, 210, 460, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80', '🥑', 107),
(8, 'Norwegian Teriyaki Salmon Quinoa Bowl', 'Pan-Asian', 'hifi', ARRAY['high-protein','muscle-gain'], 18, ARRAY['1-pan'], 1, '[{"text":"Simmer quinoa in 1 cup water with salt until tender and fluffy.","timer_seconds":600},{"text":"Sear seasoned salmon fillet skin-side down for 4 mins, flip for 3 mins.","timer_seconds":420},{"text":"Pour soy sauce, honey, and minced garlic over salmon in pan to glaze.","timer_seconds":60},{"text":"Assemble over quinoa, garnish with toasted seeds.","tip":"Omega-3 powerhouse with 42g pure protein."}]'::jsonb, '{"kcal":680,"protein":44,"carbs":48,"fats":32,"fiber":6}'::jsonb, 380, 720, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80', '🍣', 108),
(9, 'Mumbai Street-Style Egg Bhurji & Pav', 'Indian', 'broke', ARRAY['high-protein','15-min'], 10, ARRAY['1-pan','hostel-friendly'], 1, '[{"text":"Heat butter in pan, add cumin, chopped onions, and green chillies.","timer_seconds":90},{"text":"Add chopped tomatoes, turmeric, and pav bhaji/garam masala.","timer_seconds":90},{"text":"Whisk 3 eggs with salt, pour into pan and scramble gently over medium heat.","timer_seconds":150},{"text":"Toast pav on the buttery pan and serve with coriander.","tip":"Street food comfort with 24g bioavailable protein."}]'::jsonb, '{"kcal":430,"protein":25,"carbs":32,"fats":22,"fiber":3.5}'::jsonb, 42, 130, 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=600&q=80', '🍳', 109),
(10, 'Dorm Room Soya Keema Bhurji', 'Indian', 'broke', ARRAY['high-protein','muscle-gain'], 15, ARRAY['1-pan','kettle-only'], 1, '[{"text":"Soak soya chunks in boiling water for 8 mins, then squeeze dry and mince.","timer_seconds":480},{"text":"Heat oil, sauté cumin, onions, ginger, and garlic.","timer_seconds":120},{"text":"Add tomatoes, turmeric, red chilli, and garam masala.","timer_seconds":120},{"text":"Toss minced soya, cook for 4 minutes with a splash of water.","timer_seconds":240}]'::jsonb, '{"kcal":360,"protein":36,"carbs":28,"fats":11,"fiber":9}'::jsonb, 28, 115, 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=600&q=80', '🥘', 110),
(11, 'Hero Curry with Farm Veggies', 'Indian', 'balanced', ARRAY['high-protein','muscle-gain'], 23, ARRAY['oven','induction'], 1, '[{"text":"Prep ingredients and heat cooking surface.","timer_seconds":60,"tip":"Keep everything measured beforehand."},{"text":"Cook base Curry gently with spices and season to taste.","timer_seconds":1035},{"text":"Garnish with fresh herbs and serve immediately hot.","tip":"Pair with warm tea or cold yogurt."}]'::jsonb, '{"kcal":361,"protein":34.33,"carbs":59.13,"fats":14.01,"fiber":6.93}'::jsonb, 94.8, 192.4, 'https://images.unsplash.com/photo-1621996346565-e3d5d6281691?auto=format&fit=crop&w=600&q=80', '🥘', 11),
(12, 'Hero Greek Yogurt Parfait with Garlic Crunch', 'Continental', 'balanced', ARRAY['high-protein','muscle-gain'], 18, ARRAY['oven'], 1, '[{"text":"Prep ingredients and heat cooking surface.","timer_seconds":60,"tip":"Keep everything measured beforehand."},{"text":"Cook base Greek Yogurt Parfait gently with spices and season to taste.","timer_seconds":810},{"text":"Garnish with fresh herbs and serve immediately hot.","tip":"Pair with warm tea or cold yogurt."}]'::jsonb, '{"kcal":424,"protein":13.08,"carbs":32.17,"fats":17.23,"fiber":4.56}'::jsonb, 89.92, 176, 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&w=600&q=80', '🍨', 12),
(13, 'Hero Acai Superfood Bowl with Herb Spices', 'Continental', 'hifi', ARRAY['muscle-gain','muscle-gain'], 24, ARRAY['mixer'], 1, '[{"text":"Prep ingredients and heat cooking surface.","timer_seconds":60,"tip":"Keep everything measured beforehand."},{"text":"Cook base Acai Superfood Bowl gently with spices and season to taste.","timer_seconds":1080},{"text":"Garnish with fresh herbs and serve immediately hot.","tip":"Pair with warm tea or cold yogurt."}]'::jsonb, '{"kcal":597,"protein":13.34,"carbs":53.9,"fats":17.8,"fiber":7.33}'::jsonb, 275.09, 476.85, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80', '🫐', 13),
